import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DaGSOal_.js";const u=JSON.parse('{"title":"Common Workflows","description":"Practical Unreal Engine workflows using Deblx editor plugins.","frontmatter":{"title":"Common Workflows","description":"Practical Unreal Engine workflows using Deblx editor plugins."},"headers":[],"relativePath":"workflows.md","filePath":"workflows.md","lastUpdated":1794040252000}'),s={name:"workflows.md"};function i(n,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h1><p>This collection covers everyday Unreal Engine tasks and links to the relevant Deblx plugin guides. The steps assume <strong>Unreal Engine 5.1+</strong> and a correctly installed plugin.</p><h2 id="prepare-a-project-for-a-release" tabindex="-1">Prepare a Project for a Release <a class="header-anchor" href="#prepare-a-project-for-a-release" aria-label="Permalink to &quot;Prepare a Project for a Release&quot;">​</a></h2><p>Before packaging a game, inspect asset usage, review duplicate content and check loading transitions.</p><ol><li><strong>Inspect asset sizes.</strong> Run <a href="/asset-size-analyzer/usage">Asset Size Analyzer</a> across your Content folder. Sort by file size and inspect unexpectedly large assets.</li><li><strong>Review duplicate content.</strong> Use <a href="/duplicate-asset-detector/usage">Duplicate Asset Detector Pro</a> to locate potentially redundant assets.</li><li><strong>Review references before cleanup.</strong> Check referencers, save your work and keep a source-control checkpoint before deleting or consolidating assets.</li><li><strong>Check loading transitions.</strong> Configure <a href="/loading-screen-pro/usage">Loading Screen Pro</a> and verify the result in a packaged game or Launch session.</li><li><strong>Track follow-ups.</strong> Add remaining TODOs with <a href="/quick-notes/usage">Quick Notes / ToDo</a>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Asset analysis and duplicate detection help highlight candidates for optimization, but do not replace performance profiling or a backup strategy. Validate changes in a separate build before shipping.</p></div><h2 id="investigate-a-large-project" tabindex="-1">Investigate a Large Project <a class="header-anchor" href="#investigate-a-large-project" aria-label="Permalink to &quot;Investigate a Large Project&quot;">​</a></h2><p>When disk usage grows unexpectedly:</p><ol><li>Open <a href="/asset-size-analyzer/usage">Asset Size Analyzer</a> and scan the affected folder.</li><li>Narrow the result set using file size and asset type filters.</li><li>Export a CSV report if you need to track changes between builds.</li><li>Scan related folders with <a href="/duplicate-asset-detector/usage">Duplicate Asset Detector Pro</a>.</li><li>Check project references and dependencies before removing any content.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Disk size and estimated memory footprint are different measurements. Unreal Engine cooking, compression and streaming can change actual runtime memory use.</p></div><h2 id="manage-review-notes-inside-the-editor" tabindex="-1">Manage Review Notes Inside the Editor <a class="header-anchor" href="#manage-review-notes-inside-the-editor" aria-label="Permalink to &quot;Manage Review Notes Inside the Editor&quot;">​</a></h2><ol><li>Place a <strong>Quick Note</strong> in the viewport where the issue is visible.</li><li>Attach a note to a specific Blueprint node when the issue belongs to a graph.</li><li>Use categories and priorities to distinguish bugs from ordinary follow-up tasks.</li><li>Review active notes from the Overview Panel and mark completed items as resolved.</li><li>Export notes when you need to share the findings outside the project.</li></ol><p>See <a href="/quick-notes/features">Quick Notes features</a> and the <a href="/quick-notes/usage">usage guide</a>.</p><h2 id="create-loading-screens-without-custom-ui-code" tabindex="-1">Create Loading Screens Without Custom UI Code <a class="header-anchor" href="#create-loading-screens-without-custom-ui-code" aria-label="Permalink to &quot;Create Loading Screens Without Custom UI Code&quot;">​</a></h2><ol><li>Install and enable <a href="/loading-screen-pro/installation">Loading Screen Pro</a>.</li><li>Create or select the loading screen Data Asset.</li><li>Configure the image sequence, visual style, music and tips.</li><li>Preview the settings in the editor.</li><li>Validate the loading screen during transitions in a packaged game.</li></ol><p>See the <a href="/loading-screen-pro/usage">complete configuration guide</a> and <a href="/loading-screen-pro/troubleshooting">troubleshooting</a>.</p><h2 id="keeping-the-project-clean" tabindex="-1">Keeping the Project Clean <a class="header-anchor" href="#keeping-the-project-clean" aria-label="Permalink to &quot;Keeping the Project Clean&quot;">​</a></h2><p>A regular maintenance pass can combine these tools:</p><table tabindex="0"><thead><tr><th>Goal</th><th>Recommended guide</th></tr></thead><tbody><tr><td>Reduce unnecessary duplicate content</td><td><a href="/duplicate-asset-detector/usage">Duplicate Asset Detector Pro</a></td></tr><tr><td>Locate oversized project assets</td><td><a href="/asset-size-analyzer/usage">Asset Size Analyzer</a></td></tr><tr><td>Track editor TODOs and bug markers</td><td><a href="/quick-notes/usage">Quick Notes / ToDo</a></td></tr><tr><td>Improve level-loading presentation</td><td><a href="/loading-screen-pro/usage">Loading Screen Pro</a></td></tr></tbody></table><p>Need help with a workflow? Use the <a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Help Center</a>.</p>',20)])])}const h=a(s,[["render",i]]);export{u as __pageData,h as default};
